    Bug 1973062 - Use the correct URL scheme for EWS attachments. r=tobyp


    Attachments URLs are expected to use the `x-moz-ews` scheme since they are
    derived from the URLs used in message channels.

    Differential Revision: https://phabricator.services.mozilla.com/D254406

diff --git a/mail/modules/AttachmentInfo.sys.mjs b/mail/modules/AttachmentInfo.sys.mjs
index dab95d2b3f8..d4ca440031a 100644
--- a/mail/modules/AttachmentInfo.sys.mjs
+++ b/mail/modules/AttachmentInfo.sys.mjs
@@ -613,7 +613,7 @@ export class AttachmentInfo {
     }

     // Don't allow http for other cases.
-    return /^(file|data|mailbox|imap|s?news|ews):/i.test(this.url);
+    return /^(file|data|mailbox|imap|s?news|x-moz-ews):/i.test(this.url);
   }

